import {Mode} from './mode-base.js';
import {THREE,box,cylinder,ring,moveActor,distance,palette} from './world.js';
import {ball,clamp,stepBall,sweptDistance,chalk,streetGoal,ringTarget} from './ball-physics.js';

const names=['YOU','KOJO','NII','KOFI'];
const colors=[0xc05336,0x326b85,0xb59546,0x468367];
export function footballVariant(ctx){const C={fourcorners:FourCorners,penalties:Penalties,onepole:OnePole,laski:Laski}[ctx.game.id];return C?new C(ctx):null;}

export class FourCorners extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([0,12,17,0,.4,0]);this.goals=[];this.players=[];this.active=[true,true,true,true];this.conceded=[0,0,0,0];this.lastTouch=-1;this.cool=0;this.phase='serve';this.round=0;this.time=0;this.rank=null;this.aim=1;
  for(let i=0;i<4;i++){const x=i%2?7:-7,z=i<2?7:-7,n=new THREE.Vector3(x,0,z).normalize();const goal=streetGoal(this.root,x,z,Math.atan2(-n.z,n.x),2,1.25);this.goals.push({center:new THREE.Vector3(x,0,z),normal:n,mesh:goal});const p=this.player(x*.7,z*.7,i?colors[i]:this.settings.color);p.rotation.y=Math.atan2(-x,-z);p.userData.id=i;this.players.push(p);this.text(names[i],x,1.65,z,'#eddcb0',.22);}
  for(const [x,z,w,d]of [[0,-9,18,.035],[0,9,18,.035],[-9,0,.035,18],[9,0,.035,18]])chalk(this.root,x,z,w,d);
  this.you=this.players[0];this.b=ball(this.root);this.v=new THREE.Vector3();this.b.position.set(0,2.5,0);this.marker=this.circle(this.you.position.x,this.you.position.z,.48);this.targetMarker=this.circle(7,7,.7,0xa9c8d0);this.setActions([{id:'kick',label:'One-touch kick',key:'Space',charge:true},{id:'target',label:'Next goal',key:'E'},{id:'sprint',label:'Sprint',key:'Shift',hold:true}]);this.note('Four players. Defend your corner. One touch until someone else touches. E selects a goal.');this.charge=null;
 }
 hold(){if(this.phase==='play')this.charge=this.age;}
 action(id){if(id==='target'){const others=this.active.flatMap((a,i)=>a&&i!==0?[i]:[]);this.aim=others[(others.indexOf(this.aim)+1)%others.length]??0;return;}if(this.phase!=='play'||!this.active[0])return;const force=this.charge===null?.45:clamp(this.age-this.charge,.1,1);this.charge=null;this.kick(0,this.aim,force);}
 kick(i,target,power=.5){if(!this.active[i]||!this.active[target]||target===i||this.lastTouch===i||this.cool>0||distance(this.players[i],this.b)>1.05||this.b.position.y>1.3)return false;const aim=this.goals[target].center.clone().sub(this.b.position);aim.y=0;this.v.copy(aim.normalize().multiplyScalar(9+power*8));this.v.y=.6;this.lastTouch=i;this.cool=.18;this.players[i].userData.kick=.38;this.ui.sound('kick');return true;}
 concede(i){if(!this.active[i])return;this.active[i]=false;this.conceded[i]++;this.players[i].visible=false;this.goals[i].mesh.visible=false;this.round++;this.phase='result';this.time=0;this.note(`${names[i]} conceded and leaves. ${this.active.filter(Boolean).length} players remain.`);this.ui.sound('call');if(i===0){this.rank=this.active.filter(Boolean).length+1;this.finish('YOUR CORNER WAS BEATEN',`You finished ${this.rank}${this.rank===2?'nd':this.rank===3?'rd':'th'}. One conceded goal eliminates a defender.`,false);}else if(this.active.filter(Boolean).length===1){this.score=3;this.finish('LAST CORNER STANDING','You protected your goal through the knockout.');}}
 hit({point}){this.input.target=point;}
 update(dt){this.cool=Math.max(0,this.cool-dt);this.ui.power?.(this.charge===null?0:clamp(this.age-this.charge,0,1));this.status(`${this.active.filter(Boolean).length} CORNERS LEFT`,this.phase==='play'?(this.lastTouch===0?'WAIT FOR ANOTHER TOUCH':'TARGET: '+names[this.aim]):'THROW-IN · WAIT FOR THE BOUNCE');
  if(this.phase==='result'){if(this.time>1.8){this.phase='serve';this.time=0;this.lastTouch=-1;this.b.position.set(0,2.5,0);this.v.set((Math.random()-.5)*2,0,(Math.random()-.5)*2);}return;}
  if(this.phase==='serve'){stepBall(this.b,this.v,dt);if(this.b.position.y<=.14){this.phase='play';this.lastTouch=-1;this.note('Ball bounced. Play!');}return;}
  this.move(this.you,dt,this.input.sprint?6.2:4.4,8.5);this.you.position.z=clamp(this.you.position.z,-8.5,8.5);this.marker.position.set(this.you.position.x,.04,this.you.position.z);
  if(!this.active[this.aim])this.aim=this.active.findIndex((a,i)=>a&&i!==0);if(this.aim>=0)this.targetMarker.position.set(this.goals[this.aim].center.x,.04,this.goals[this.aim].center.z);
  for(let i=1;i<4;i++){if(!this.active[i])continue;const p=this.players[i],home=this.goals[i].center.clone().multiplyScalar(.72),can=this.lastTouch!==i;const target=can&&distance(p,this.b)<9?this.b.position:home;p.userData.run=moveActor(p,target,3.1,dt);if(can&&distance(p,this.b)<1){const targets=this.active.flatMap((a,j)=>a&&j!==i?[j]:[]);this.kick(i,targets[Math.floor(Math.random()*targets.length)],.3+Math.random()*.4);}}
  const prev=stepBall(this.b,this.v,dt,{drag:.22});for(let i=0;i<4;i++){if(!this.active[i])continue;const g=this.goals[i],before=prev.clone().sub(g.center).dot(g.normal),after=this.b.position.clone().sub(g.center).dot(g.normal);if(before<=0&&after>0){const t=-before/(after-before),cross=prev.clone().lerp(this.b.position,t),side=new THREE.Vector3(-g.normal.z,0,g.normal.x);if(Math.abs(cross.clone().sub(g.center).dot(side))<1&&cross.y<1.25){this.concede(i);return;}}}
  if(Math.abs(this.b.position.x)>10||Math.abs(this.b.position.z)>10||this.v.length()<.15){this.phase='result';this.time=.8;this.note('Out of play. A fresh throw-in; no defender eliminated.');}
 }
}

export class Penalties extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([1.5,3.4,8,0,1,-6]);streetGoal(this.root,0,-9,Math.PI/2,5.5,2.4);chalk(this.root,0,-9,5.5,.06);chalk(this.root,0,0,.18,.18);for(const x of [-5,5])chalk(this.root,x,-5,.04,8);this.you=this.player(-.4,1);this.cpu=this.player(0,-8.6,0x326b85);this.you.rotation.y=Math.PI;this.cpu.rotation.y=0;this.b=ball(this.root);this.v=new THREE.Vector3();this.target=ringTarget(this.root);this.aimX=0;this.aimY=.7;this.scores=[0,0];this.shots=[0,0];this.turn=0;this.phase='aim';this.charge=null;this.dive=0;this.diveAge=0;this.goalX=0;this.power=.5;this.prepare();}
 prepare(){this.phase='aim';this.time=0;this.b.position.set(0,.12,0);this.v.set(0,0,0);this.dive=0;this.diveAge=0;this.saved=false;this.charge=null;this.you.userData.pose=this.cpu.userData.pose='idle';this.you.userData.jump=this.cpu.userData.jump=0;this.you.userData.lean=this.cpu.userData.lean=0;this.goalX=0;
  if(this.turn===0){this.you.position.set(-.4,0,1);this.cpu.position.set(0,0,-8.6);this.you.rotation.y=Math.PI;this.cpu.rotation.y=0;this.setActions([{id:'shoot',label:'Hold / shoot',key:'Space',charge:true}]);this.note('Aim left/right; up/down changes height. Hold Shoot for power. Five penalties each, then sudden death.');this.world.aimPlane=new THREE.Plane(new THREE.Vector3(0,0,1),9);}
  else{this.you.position.set(0,0,-8.6);this.cpu.position.set(-.4,0,1);this.you.rotation.y=0;this.cpu.rotation.y=Math.PI;this.cpuAim=(Math.random()-.5)*4.6;this.cpuHeight=.3+Math.random()*1.5;this.releaseAt=1.7+Math.random();this.setActions([{id:'left',label:'Dive left',key:'Q'},{id:'center',label:'Stay centre',key:'Space'},{id:'right',label:'Dive right',key:'E'}]);this.note('Your turn in goal. Watch the strike and choose a dive.');this.world.aimPlane=null;}
 }
 hold(){if(this.turn===0&&this.phase==='aim')this.charge=this.age;}
 action(id){if(this.turn===0&&this.phase==='aim'){const power=this.charge===null?.5:clamp((this.age-this.charge)/1.1,.2,1);this.launch(this.aimX,this.aimY,power);this.charge=null;}else if(this.turn===1&&['aim','flight'].includes(this.phase)&&this.dive===0){this.dive=id==='left'?-1:id==='right'?1:2;this.diveAge=0;this.you.userData.pose='cheer';}}
 launch(x,y,power){this.phase='flight';this.time=0;const duration=.85-power*.42;this.v.set(x/duration,(y-.12+4.905*duration*duration)/duration,-9/duration);this.shooter=this.turn===0?this.you:this.cpu;this.shooter.userData.kick=.38;this.ui.sound('kick');this.cpuReact=.19+Math.random()*.13;this.cpuDive=clamp(x+(Math.random()-.5)*2,-2.5,2.5);}
 hit({point}){if(this.turn===0&&this.phase==='aim'){this.aimX=clamp(point.x,-3.3,3.3);this.aimY=clamp(point.y,.15,3.1);}}
 resolve(goal,message){if(this.phase==='result')return;this.shots[this.turn]++;if(goal)this.scores[this.turn]++;this.phase='result';this.time=0;this.note(message);this.ui.sound(goal?'goal':'miss');}
 update(dt){this.status(`YOU ${this.scores[0]} — ${this.scores[1]} THEM`,`${this.turn?'SAVE':'SHOOT'} · ${this.shots[0]} / ${this.shots[1]} TAKEN`);this.target.visible=this.turn===0&&this.phase==='aim';if(this.target.visible){const v=this.input.vector();this.aimX=clamp(this.aimX+v.x*dt*2,-3.3,3.3);this.aimY=clamp(this.aimY-v.z*dt*1.5,.15,3.1);this.target.position.set(this.aimX,this.aimY,-8.96);this.ui.power?.(this.charge===null?.5:clamp((this.age-this.charge)/1.1,0,1));}
  if(this.phase==='aim'&&this.turn===1&&this.time>this.releaseAt)this.launch(this.cpuAim,this.cpuHeight,.5+Math.random()*.3);
  if(this.phase==='flight'){const prev=stepBall(this.b,this.v,dt,{drag:.12,bounce:.4}),keeper=this.turn===0?this.cpu:this.you;if(this.turn===0&&this.time>this.cpuReact){keeper.position.x=THREE.MathUtils.damp(keeper.position.x,this.cpuDive,5,dt);keeper.userData.pose='cheer';keeper.userData.jump=Math.sin(clamp((this.time-this.cpuReact)*2,0,1)*Math.PI)*.45;keeper.userData.lean=-Math.sign(this.cpuDive)*.65;}
   if(this.turn===1&&this.dive){this.diveAge+=dt;const dest=this.dive===2?0:this.dive*2.3;keeper.position.x=THREE.MathUtils.damp(keeper.position.x,dest,7,dt);keeper.userData.jump=Math.sin(clamp(this.diveAge/.8,0,1)*Math.PI)*.5;keeper.userData.lean=this.dive===2?0:-this.dive*.85;}
   const reach=keeper.userData.pose==='cheer'?.85:.45;if(!this.saved&&prev.z>=-8.7&&this.b.position.z<=-8.35&&Math.abs(this.b.position.x-keeper.position.x)<reach&&this.b.position.y<1.8+(keeper.userData.jump||0)){this.saved=true;this.v.z=Math.abs(this.v.z)*.5;this.v.x+=(Math.random()-.5)*7;this.v.y=2;this.resolve(false,'Saved! The keeper got a hand to it.');}
   else if(prev.z>-9&&this.b.position.z<=-9){const u=(-9-prev.z)/(this.b.position.z-prev.z),cross=prev.clone().lerp(this.b.position,u);const goal=Math.abs(cross.x)<2.75&&cross.y<2.4;this.resolve(goal,goal?'Goal! Into the corner.':'Wide or over. No goal.');}else if(this.time>2)this.resolve(false,'The shot did not cross the goal.');
  }else if(this.phase==='result'&&this.time>1.5){const equal=this.shots[0]===this.shots[1];if(equal&&this.shots[0]>=5&&this.scores[0]!==this.scores[1]){this.score=this.scores[0];return this.finish(this.score>this.scores[1]?'SHOOTOUT WON':'SHOOTOUT LOST',`${this.scores[0]}–${this.scores[1]} after ${this.shots[0]} penalties each.`,this.score>this.scores[1]);}this.turn=1-this.turn;this.prepare();}
 }
}

export class OnePole extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([2.6,4.6,14,0,.7,-1]);this.players=[this.player(-1,8),this.player(1,-8,0x326b85)];this.you=this.players[0];this.players[0].rotation.y=Math.PI;this.poles=[];for(const z of [-10,10]){const pole=cylinder(.075,.09,1.35,0x8e7652,0,.675,z,this.root,12);pole.rotation.z=.025;this.poles.push(pole);chalk(this.root,0,z>0?7:-7,4,.04);}this.b=ball(this.root);this.v=new THREE.Vector3();this.target=this.circle(0,-10,.25);this.scores=[0,0];this.shots=[0,0];this.turn=0;this.phase='aim';this.aim=0;this.charge=null;this.prepare();}
 prepare(){this.phase='aim';this.time=0;this.charge=null;this.b.position.set(0,.12,this.turn?-8:8);this.v.set(0,0,0);this.setActions(this.turn?[{id:'wait',label:'Their shot',key:'Space',disabled:true}]:[{id:'shoot',label:'Hold / strike',key:'Space',charge:true}]);this.note(this.turn?'Their turn. Only a direct hit on your pole scores.':'Aim at the far pole. Hold Strike for pace; release to kick. Six shots each; most pole hits wins.');}
 hold(){if(this.turn===0&&this.phase==='aim')this.charge=this.age;}
 action(){if(this.turn||this.phase!=='aim')return;this.launch(this.aim,this.charge===null?.55:clamp((this.age-this.charge)/1.1,.15,1));this.charge=null;}
 launch(aim,power){this.phase='flight';this.time=0;const direction=this.turn?1:-1;this.v.set(Math.sin(aim)*(12+power*13),.35,direction*Math.cos(aim)*(12+power*13));this.players[this.turn].userData.kick=.38;this.ui.sound('kick');}
 hit({point}){if(!this.turn&&this.phase==='aim')this.aim=clamp(Math.atan2(point.x,8-point.z),-.3,.3);}
 resolve(hit){if(this.phase!=='flight')return;this.shots[this.turn]++;if(hit){this.scores[this.turn]++;this.poles[this.turn?1:0].rotation.z=.18;}this.phase='result';this.time=0;this.note(hit?'Direct pole hit — one point.':'Miss. Crossing the end line does not score.');this.ui.sound(hit?'point':'miss');}
 update(dt){this.status(`YOU ${this.scores[0]} — ${this.scores[1]} THEM`,`${this.turn?'THEIR':'YOUR'} SHOT · ${this.shots[this.turn]+1} / 6`);if(this.phase==='aim'){if(!this.turn){this.aim=clamp(this.aim+this.input.vector().x*dt*.18,-.3,.3);this.target.position.set(Math.tan(this.aim)*18,.035,-10);this.ui.power?.(this.charge===null?.55:clamp((this.age-this.charge)/1.1,0,1));}else if(this.time>1.5)this.launch((Math.random()-.5)*.045,.6+Math.random()*.3);}else if(this.phase==='flight'){const before=stepBall(this.b,this.v,dt,{drag:.16}),z=this.turn?10:-10,p=new THREE.Vector3(0,clamp(this.b.position.y,.12,1.35),z);if(sweptDistance(before,this.b.position,p)<.195&&this.b.position.y<1.47)this.resolve(true);else if(Math.abs(this.b.position.z)>11||Math.abs(this.b.position.x)>4||this.time>4)this.resolve(false);}else if(this.time>1.5){if(this.shots.every(x=>x>=6)){this.score=this.scores[0];this.finish(this.score===this.scores[1]?'LEVEL ON POLE HITS':this.score>this.scores[1]?'ONE POLE WON':'THEY TAKE THE DUEL',`${this.score}–${this.scores[1]} direct hits from six shots each.`,this.score>=this.scores[1]);}else{this.turn=1-this.turn;this.poles.forEach(p=>p.rotation.z=.025);this.prepare();}}}
}

export class Laski extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([3,5.3,13,0,.8,-3]);streetGoal(this.root,0,-9,Math.PI/2,5,2.2);this.players=[this.player(0,5),this.player(-3,1,0x326b85),this.player(3,1,0xb59546),this.player(0,-2,0x468367)];this.players.forEach((p,i)=>p.userData.id=i);this.you=this.players[0];this.keeper=this.player(0,-8.2,0xc5c0a1);this.keeper.rotation.y=0;this.active=[true,true,true,true];this.b=ball(this.root);this.v=new THREE.Vector3();this.lastTouch=-1;this.phase='serve';this.cool=0;this.possessor=null;this.charge=null;this.keeperRole=false;this.selectedOut=1;this.you.rotation.y=Math.PI;this.marker=this.circle(0,5,.48);this.setPlayingActions();this.serve();}
 setPlayingActions(){this.setActions(this.keeperRole?[{id:'throw',label:'Throw in',key:'Space',charge:true},{id:'dive',label:'Dive / save',key:'E'}]:[{id:'shoot',label:'Shoot / tackle',key:'Space',charge:true},{id:'volley',label:'Volley',key:'E'},{id:'sprint',label:'Sprint',key:'Shift',hold:true}]);}
 serve(){this.phase='serve';this.time=0;this.possessor=null;this.lastTouch=-1;this.b.position.set(this.keeper.position.x,1.2,-7.8);this.v.set(0,0,0);this.charge=null;this.note(this.keeperRole?'You are keeping. Throw the ball into the players.':'The keeper throws in. Win the ball and score to choose who leaves.');}
 throwIn(){this.phase='play';this.time=0;this.v.set((Math.random()-.5)*3,5.5,8);this.keeper.userData.pose='point';this.cool=.5;this.ui.sound('swing');}
 hold(){if(['play','serve'].includes(this.phase))this.charge=this.age;}
 action(id){if(this.phase==='choose'){if(id.startsWith('out-'))this.eliminate(Number(id.slice(4)));return;}if(this.phase==='winner'){if(id==='keeper'||id==='player')this.newGame(id==='keeper');else if(id==='continue')this.nextRound();return;}if(this.keeperRole){if(this.phase==='serve'&&id==='throw')this.throwIn();else if(this.phase==='play'){this.keeper.userData.pose='cheer';this.dive=.8;}return;}if(this.phase!=='play'||!this.active[0])return;
  if(this.possessor&&this.possessor!==this.you){if(distance(this.you,this.possessor)<1.35){this.possessor=null;this.cool=.1;this.v.set(Math.sin(this.you.rotation.y)*4,.4,Math.cos(this.you.rotation.y)*4);this.ui.sound('kick');}return;}
  if(distance(this.you,this.b)<1.2&&this.b.position.y<(id==='volley'?2.2:.85)){const raw=this.input.vector(),power=this.charge===null?.5:clamp((this.age-this.charge)/1.1,.1,1);this.strike(0,clamp(raw.x*2,-2,2),power,id==='volley');}this.charge=null;
 }
 strike(i,targetX,power=.6,volley=false){const p=this.players[i],d=new THREE.Vector3(targetX,.5,-10).sub(this.b.position);d.y=0;this.v.copy(d.normalize().multiplyScalar(13+power*10));this.v.y=volley?1.1:1.2+power;this.possessor=null;this.lastTouch=i;this.cool=.3;p.userData.kick=.38;this.ui.sound('kick');}
 scored(i){if(!this.active[i]||i<0)return;this.lastScorer=i;this.phase='choose';this.time=0;this.v.set(0,0,0);this.possessor=null;this.ui.sound('goal');const others=this.active.flatMap((a,j)=>a&&j!==i?[j]:[]);if(i===0&&!this.keeperRole){this.setActions(others.map((j,k)=>({id:'out-'+j,label:'Eliminate '+names[j],key:['Space','E','Q'][k]})));this.note('You scored. Choose ONE player to eliminate.');}else{this.selectedOut=others.slice().sort((a,b)=>distance(this.players[a],this.keeper)-distance(this.players[b],this.keeper))[0];this.note(`${this.playerName(i)} scored and is choosing a player to eliminate.`);}}
 eliminate(i){if(this.phase!=='choose'||!this.active[i]||i===this.lastScorer)return false;this.active[i]=false;this.players[i].visible=false;const remaining=this.active.flatMap((a,j)=>a?[j]:[]);if(i===0&&!this.keeperRole){this.score=4-remaining.length;this.finish('ELIMINATED BY THE SCORER',`${this.playerName(this.lastScorer)} chose you after scoring. ${remaining.length} players remain.`,false);return true;}if(remaining.length===1){this.phase='winner';this.time=0;this.winner=remaining[0];if(this.winner===0&&!this.keeperRole){this.setActions([{id:'keeper',label:'Be keeper next',key:'Space'},{id:'player',label:'Play again',key:'E'}]);this.note('You are the last player. Choose keeper or player for the next game.');}else{this.nextKeeper=Math.random()<.5;this.setActions([{id:'continue',label:'Next game',key:'Space'}]);this.note(`${this.playerName(this.winner)} wins and chooses to ${this.nextKeeper?'keep':'play again'}.`);}}else{this.setPlayingActions();this.serve();}return true;}
 playerName(i){return i===0&&this.keeperRole?'KWESI':names[i];}
 nextRound(){if(this.nextKeeper&&this.keeperRole){const winner=this.players[this.winner];this.players[this.winner]=this.keeper;this.keeper=winner;[this.players[0],this.players[this.winner]]=[this.players[this.winner],this.players[0]];this.keeperRole=false;}this.newGame(this.nextKeeper?false:this.keeperRole);}
 newGame(keeperRole){if(keeperRole&&!this.keeperRole)[this.keeper,this.players[0]]=[this.players[0],this.keeper];this.keeperRole=keeperRole;this.active=[true,true,true,true];for(let i=0;i<4;i++){this.players[i].userData.id=i;this.players[i].visible=true;this.players[i].position.set([-3,3,-3,3][i],0,[4,4,0,0][i]);}this.keeper.position.set(0,0,-8.2);this.keeper.rotation.y=0;this.keeper.visible=true;this.you=keeperRole?this.keeper:this.players[0];this.setPlayingActions();this.serve();}
 hit({point,id}){if(this.phase==='choose'&&typeof id==='number')this.eliminate(id);else this.input.target=point;}
 update(dt){this.cool=Math.max(0,this.cool-dt);this.status(`${this.active.filter(Boolean).length} PLAYERS LEFT`,this.phase==='winner'?'WINNER CHOOSES NEXT ROLE':this.phase==='choose'?'SCORER CHOOSES ELIMINATION':this.keeperRole?'YOU ARE KEEPING':'ONE KEEPER · EVERY PLAYER FOR THEMSELVES');
  if(this.phase==='winner'){if(this.winner!==0||this.keeperRole){if(this.time>3)this.nextRound();}return;}
  if(this.phase==='choose'){if((this.lastScorer!==0||this.keeperRole)&&this.time>1.5)this.eliminate(this.selectedOut);return;}
  if(this.phase==='serve'){this.keeper.userData.pose='point';this.b.position.set(this.keeper.position.x,1.2,-7.8);if(!this.keeperRole&&this.time>1.8)this.throwIn();return;}
  if(this.keeperRole){const v=this.input.vector();this.keeper.position.x=clamp(this.keeper.position.x+v.x*dt*5,-2.5,2.5);this.keeper.position.z=-8.3;this.dive=Math.max(0,(this.dive||0)-dt);this.keeper.userData.pose=this.dive?'cheer':'idle';}else{this.move(this.you,dt,this.input.sprint?7:5,8);this.you.position.z=clamp(this.you.position.z,-8,9);this.marker.position.set(this.you.position.x,.03,this.you.position.z);this.keeper.position.x=THREE.MathUtils.damp(this.keeper.position.x,clamp(this.b.position.x*.65,-2,2),2.2,dt);this.keeper.userData.pose=this.b.position.z<-5?'cheer':'idle';}
  for(let i=0;i<4;i++){if(!this.active[i]||i===0&&!this.keeperRole)continue;const p=this.players[i];p.userData.run=moveActor(p,this.possessor===p?{x:p.position.x*.9,z:-4.8}:this.b.position,3.5,dt);p.position.z=clamp(p.position.z,-7,9);if(this.possessor===p&&this.cool<=0&&p.position.z<-1&&Math.random()<dt*2)this.strike(i,(Math.random()-.5)*4,.5+Math.random()*.4);}
  // Body separation matters when several players contest the same ball.
  const field=this.players.filter((p,i)=>this.active[i]);for(let i=0;i<field.length;i++)for(let j=i+1;j<field.length;j++){const a=field[i],b=field[j],d=distance(a,b);if(d>.001&&d<.65){const v=a.position.clone().sub(b.position).normalize().multiplyScalar((.65-d)*.5);a.position.add(v);b.position.sub(v);}}
  if(this.possessor){const p=this.possessor;this.b.position.set(p.position.x+Math.sin(p.rotation.y)*.5,.12,p.position.z+Math.cos(p.rotation.y)*.5);this.v.set(0,0,0);this.lastTouch=p.userData.id;}else{const prev=stepBall(this.b,this.v,dt,{drag:.45});if(prev.z>-9&&this.b.position.z<=-9&&Math.abs(this.b.position.x)<2.5&&this.b.position.y<2.2&&this.lastTouch>=0){this.scored(this.lastTouch);return;}if(this.b.position.z<-7.8&&Math.abs(this.b.position.x-this.keeper.position.x)<(this.dive?.95:.65)&&this.b.position.y<2&&this.v.z<0){this.v.z=Math.abs(this.v.z)*.7;this.v.y=2.5;this.lastTouch=-1;this.cool=.25;this.ui.sound('clap');this.note('Saved — the rebound is live.');}
   if(this.cool<=0&&this.b.position.y<.7){const nearest=field.slice().sort((a,b)=>distance(a,this.b)-distance(b,this.b))[0];if(nearest&&distance(nearest,this.b)<.75){this.possessor=nearest;this.lastTouch=nearest.userData.id;}}
  }
  if(Math.abs(this.b.position.x)>9||this.b.position.z>11||this.b.position.z<-10.5){this.serve();return;}this.ui.power?.(this.charge===null?0:clamp((this.age-this.charge)/1.1,0,1));
 }
}
